CREATE TABLE payments(id UUID PRIMARY KEY,order_id UUID NOT NULL,user_id UUID NOT NULL,amount NUMERIC(12,2) NOT NULL,currency VARCHAR(3) NOT NULL,status VARCHAR(30) NOT NULL,idempotency_key VARCHAR(100) NOT NULL UNIQUE,created_at TIMESTAMPTZ NOT NULL,updated_at TIMESTAMPTZ NOT NULL,CONSTRAINT ck_payment_status CHECK(status IN ('PENDING','SUCCEEDED','FAILED','REFUNDED')));CREATE INDEX idx_payments_order ON payments(order_id);